import{_ as i,o as t,c as s,a2 as n}from"./chunks/framework.vLhlLNVn.js";const a="/assets/einstellungen-geraet-loeschen.0XbeLZGI.png",r="/assets/konfig-manager-geraet-loeschen.Bc9kXtJe.png",d="data:image/svg+xml;base64,",k=JSON.parse('{"title":"Geräte verwalten","description":"","frontmatter":{"order":5,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/02.anleitungen/05.geraete-verwalten.md"},"headers":[],"relativePath":"de/adapter/wled/anleitungen/geraete-verwalten.md","filePath":"de/adapter/wled/anleitungen/geraete-verwalten.md","lastUpdated":null}'),l={name:"de/adapter/wled/anleitungen/geraete-verwalten.md"};function h(c,e,g,o,I,p){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="gerate-verwalten" tabindex="-1">Geräte verwalten <a class="header-anchor" href="#gerate-verwalten" aria-label="Permalink to &quot;Geräte verwalten&quot;">​</a></h1><p><a id="remove-wled-device-adapter"></a></p><h2 id="wie-entferne-ich-ein-wled-gerat-aus-dem-adapter" tabindex="-1">Wie entferne ich ein WLED-Gerät aus dem Adapter? <a class="header-anchor" href="#wie-entferne-ich-ein-wled-gerat-aus-dem-adapter" aria-label="Permalink to &quot;Wie entferne ich ein WLED-Gerät aus dem Adapter?&quot;">​</a></h2><p><strong>Kurz:</strong> Du löschst ein Gerät in den Instanzeinstellungen über den Papierkorb auf seiner Karte oder im Device Manager des Admins. Der Adapter entfernt dabei alle Datenpunkte des Geräts und beendet Verbindung und Timer. Am WLED-Gerät selbst ändert sich nichts. Läuft das Gerät noch in deinem Netz, findet der Adapter es per Bonjour wieder und legt es neu an. <strong>Ab v0.10.0</strong> kannst du die automatische Suche abschalten, dann bleibt es weg.</p><h3 id="so-gehst-du-vor-in-den-instanzeinstellungen" tabindex="-1">So gehst du vor: in den Instanzeinstellungen <a class="header-anchor" href="#so-gehst-du-vor-in-den-instanzeinstellungen" aria-label="Permalink to &quot;So gehst du vor: in den Instanzeinstellungen&quot;">​</a></h3><p><strong>Ab v0.10.0:</strong> Die Instanzeinstellungen zeigen jedes Gerät als Karte mit Online-Status, IP-Adresse und Firmware (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/266" target="_blank" rel="noreferrer">#266</a>).</p><ol><li>Öffne im Admin unter „Instanzen“ die Einstellungen von <code>wled.&lt;Instanz&gt;</code>. Der Reiter „Geräte“ ist schon offen.</li><li>Klicke auf der Karte des Geräts unten rechts auf den Papierkorb („Gerät löschen“).</li><li>Der Dialog fragt „&lt;Gerät&gt; löschen?“ und erklärt: „Das Gerät wird mit allen Datenpunkten aus ioBroker entfernt. Am WLED-Gerät selbst ändert sich nichts.“ Klicke auf „Löschen“.</li><li>Unten erscheint „&lt;Gerät&gt; wurde gelöscht.“ und die Karte verschwindet. Gibt es das Gerät schon nicht mehr, steht im Dialog „&lt;Gerät&gt; gibt es nicht mehr.“, bei einem anderen Fehler „Das hat nicht geklappt. Details stehen im Log der Instanz.“</li></ol><p><img src="'+a+'" alt="Instanzeinstellungen von wled.0, Reiter „Geräte“: Über den Gerätekarten liegt der Dialog „Balkon löschen?“ mit den Knöpfen „Abbrechen“ und „Löschen“."></p><p>Ein Gerät, das offline ist, löschst du genauso. Die Instanz muss dafür laufen. Ist sie gestoppt, zeigt der Reiter „Die Instanz läuft nicht“ und einen Knopf „Instanz starten“.</p><h3 id="so-gehst-du-vor-im-device-manager" tabindex="-1">So gehst du vor: im Device Manager <a class="header-anchor" href="#so-gehst-du-vor-im-device-manager" aria-label="Permalink to &quot;So gehst du vor: im Device Manager&quot;">​</a></h3><p>Der Device Manager ist die Geräteübersicht des Admins. In Admin 8.3 heißt der Reiter „Konfig-Manager“, in älteren Admin-Versionen „Geräte“.</p><ol><li>Öffne im Admin den Reiter „Konfig-Manager“ (oder „Geräte“) und wähle die Instanz <code>wled.&lt;Instanz&gt;</code>.</li><li>Klicke auf der Karte des Geräts auf den Papierkorb („Gerät löschen“).</li><li>Bestätige die Frage „Möchten Sie das Gerät &lt;MAC&gt; wirklich löschen?“ mit „Ja“. Die Frage nennt die MAC-Adresse aus der Objekt-ID, nicht den Namen.</li><li>Das Gerät verschwindet aus der Liste. Im Log steht <code>&lt;MAC&gt; deleted</code>. Klappt das Löschen nicht, erscheint „Gerät &lt;Gerät&gt; kann nicht gelöscht werden“.</li></ol><p><img src="'+r+'" alt="Device Manager in Admin 8.3 (Reiter „Konfig-Manager“) mit den Karten der WLED-Geräte von wled.0 und der Sicherheitsabfrage „Möchten Sie das Gerät MAC wirklich löschen?“ mit „Ja“ und „Nein“."></p><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Beim Löschen entfernt der Adapter das Geräteobjekt <code>wled.&lt;Instanz&gt;.&lt;MAC&gt;</code> mit allen Datenpunkten darunter. Skripte, VIS-Ansichten und Aliase, die auf diese Datenpunkte zeigen, laufen danach ins Leere. Legt der Adapter das Gerät später neu an, entstehen die Datenpunkte wieder unter derselben MAC.</p></div><h3 id="was-der-adapter-beim-loschen-aufraumt" tabindex="-1">Was der Adapter beim Löschen aufräumt <a class="header-anchor" href="#was-der-adapter-beim-loschen-aufraumt" aria-label="Permalink to &quot;Was der Adapter beim Löschen aufräumt&quot;">​</a></h3><p>Der Adapter stoppt für das Gerät den Watchdog und die Timer, schließt die WebSocket-Verbindung und vergisst das Gerät. Das gilt auch, wenn du das Geräteobjekt <code>wled.&lt;Instanz&gt;.&lt;MAC&gt;</code> direkt im Reiter „Objekte“ löschst. Im Log steht dann <code>Device &lt;MAC&gt; was deleted from object tree, cleaning up backend processes and objects</code>.</p><p>Kennt der Adapter das Gerät beim Löschen im Reiter „Objekte“ nicht, zum Beispiel weil es noch nie verbunden war, meldet er <code>Device &lt;MAC&gt; not found in devices array, cannot clean up backend processes and objects</code>. Die Objekte sind trotzdem gelöscht, die Warnung kannst du ignorieren.</p><h3 id="warum-taucht-das-geloschte-gerat-wieder-auf" tabindex="-1">Warum taucht das gelöschte Gerät wieder auf? <a class="header-anchor" href="#warum-taucht-das-geloschte-gerat-wieder-auf" aria-label="Permalink to &quot;Warum taucht das gelöschte Gerät wieder auf?&quot;">​</a></h3><p>Der Adapter sucht WLED-Geräte per Bonjour (mDNS). Die Suche startet beim Adapterstart und wenn du in den Instanzeinstellungen auf „Geräte suchen“ oder im Device Manager auf „Neue Geräte suchen“ klickst. Danach lauscht sie weiter, bis die Instanz stoppt. Meldet sich dabei ein Gerät, das der Adapter nicht kennt, legt er es neu an. Ein gelöschtes Gerät, das noch eingeschaltet in deinem Netz läuft, erscheint deshalb wieder. Es gibt keine Liste, mit der du einzelne Geräte von der Suche ausschließt.</p><p>Lösche ein Gerät deshalb erst, wenn du es nicht mehr betreibst oder aus dem Netz genommen hast.</p><p><strong>Ab v0.10.0:</strong> In den Instanzeinstellungen schaltest du im Reiter „Einstellungen“ unter „Erkennung“ die Option „Geräte automatisch per Bonjour/mDNS suchen“ aus (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/897" target="_blank" rel="noreferrer">#897</a>). Dann sucht der Adapter beim Start nicht mehr und nutzt nur die Geräte, die er schon kennt oder die du per IP hinzufügst. Ein gelöschtes Gerät bleibt weg. Startest du die Suche von Hand („Geräte suchen“), lauscht sie bis zum nächsten Neustart der Instanz und findet das Gerät wieder.</p><p><img src="'+d+'" alt="Ablauf: Du löschst das Gerät im Reiter „Geräte“, in den Instanzeinstellungen, im Reiter „Objekte“ oder per Skript. Der Adapter löscht die Datenpunkte und stoppt Watchdog, Timer und WebSocket. Läuft das Gerät noch im Netz, findet Bonjour es beim Adapterstart oder bei „Neue Geräte suchen“ wieder und der Adapter legt es unter derselben MAC neu an."></p><h3 id="gerat-per-skript-loschen" tabindex="-1">Gerät per Skript löschen <a class="header-anchor" href="#gerat-per-skript-loschen" aria-label="Permalink to &quot;Gerät per Skript löschen&quot;">​</a></h3><p>Mit <code>sendTo</code> löschst du ein Gerät über seine IP-Adresse. Die Antwort ist <code>success</code> oder <code>failed</code>:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;deleteDevice&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;192.168.x.y&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`Gerät löschen: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Findet der Adapter kein Gerät mit dieser IP-Adresse, steht im Log <code>Device with IP 192.168.x.y not found</code> und die Antwort ist <code>failed</code>.</p><p><strong>Ab v0.10.0:</strong> Du kannst das Gerät auch über seine MAC-Adresse löschen, so wie sie in der Objekt-ID steht. Dann ist die Antwort ein Objekt: <code>{ ok: true }</code> oder zum Beispiel <code>{ ok: false, error: &#39;notFound&#39; }</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/266" target="_blank" rel="noreferrer">#266</a>).</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;deleteDevice&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;MAC&gt;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`Gerät löschen: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ok</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ?</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;gelöscht&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> result</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">error</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><h3 id="altere-versionen" tabindex="-1">Ältere Versionen <a class="header-anchor" href="#altere-versionen" aria-label="Permalink to &quot;Ältere Versionen&quot;">​</a></h3><p><strong>Bis v0.9.3:</strong> Die Instanzeinstellungen zeigen eine Gerätetabelle. Zum Löschen klickst du in der Spalte „Entfernen“ auf den roten Knopf mit dem Papierkorb. Der Dialog „Gerät löschen Bestätigung“ zeigt Name und IP-Adresse, du bestätigst mit „Gerät löschen“. Danach erscheint „Gerät erfolgreich gelöscht“ oder „Gerät konnte nicht gelöscht werden“.</p><p><strong>Bis v0.9.2:</strong> In den Instanzeinstellungen lässt sich ein Gerät, das seit dem Adapterstart offline ist, nicht löschen. Es erscheint „Gerät konnte nicht gelöscht werden“, im Log steht <code>Device with IP 192.168.x.y not found</code>. Lösche das Gerät in diesem Fall im Device Manager oder im Reiter „Objekte“.</p><p><strong>Ab v0.9.3:</strong> Das Löschen in den Instanzeinstellungen klappt auch für Geräte, die offline sind (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/787" target="_blank" rel="noreferrer">#787</a>). Der Adapter sucht das Gerät dazu auch im Objektbaum.</p><p><strong>Bis v0.9.2:</strong> Im Device Manager wartet der Dialog nicht auf das Ergebnis und zeigt keinen Fehler an. Bei Instanzen ab <code>wled.10</code> scheitert das Löschen dort. Nutze dann den Reiter „Objekte“.</p><p><strong>Ab v0.9.3:</strong> Der Dialog im Device Manager wartet auf das Ergebnis, zeigt bei einem Fehler „Gerät &lt;Gerät&gt; kann nicht gelöscht werden“ und funktioniert auch bei Instanzen ab <code>wled.10</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/914" target="_blank" rel="noreferrer">#914</a>).</p><p><strong>Ab v0.9.3:</strong> „Neue Geräte suchen“ beendet zuerst die laufende Suche und startet dann eine neue. Es laufen keine Suchen nebeneinander (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/905" target="_blank" rel="noreferrer">#905</a>).</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erstes-geraet#adapter-wled-devices-automatically">Wie und wann findet der Adapter meine WLED-Geräte automatisch?</a> · <a href="./../erste-schritte/erstes-geraet#add-device-manually-ip-if">Wie füge ich ein Gerät manuell per IP hinzu?</a></p><p><a id="deal-switched-off-offline-devices"></a></p><h2 id="wie-gehe-ich-mit-ausgeschalteten-oder-offline-geraten-um-und-wie-werde-ich-die-log-meldungen-los" tabindex="-1">Wie gehe ich mit ausgeschalteten oder offline Geräten um, und wie werde ich die Log-Meldungen los? <a class="header-anchor" href="#wie-gehe-ich-mit-ausgeschalteten-oder-offline-geraten-um-und-wie-werde-ich-die-log-meldungen-los" aria-label="Permalink to &quot;Wie gehe ich mit ausgeschalteten oder offline Geräten um, und wie werde ich die Log-Meldungen los?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="happens-commands-sent-switched-off"></a></p><h2 id="was-passiert-mit-befehlen-an-ein-ausgeschaltetes-gerat" tabindex="-1">Was passiert mit Befehlen an ein ausgeschaltetes Gerät? <a class="header-anchor" href="#was-passiert-mit-befehlen-an-ein-ausgeschaltetes-gerat" aria-label="Permalink to &quot;Was passiert mit Befehlen an ein ausgeschaltetes Gerät?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>',42)])])}const m=i(l,[["render",h]]);export{k as __pageData,m as default};
